import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        version_part, pre = core.split('-', 1)
    else:
        version_part, pre = core, None
    major, minor, patch = (int(x) for x in version_part.split('.'))
    return (major, minor, patch, pre)

def _cmp_ident(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        if ai != bi:
            return -1 if ai < bi else 1
        return 0
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    if a < b:
        return -1
    if a > b:
        return 1
    return 0

def _compare(v1, v2):
    maj1, min1, pat1, pre1 = _parse(v1)
    maj2, min2, pat2, pre2 = _parse(v2)
    for a, b in ((maj1, maj2), (min1, min2), (pat1, pat2)):
        if a != b:
            return -1 if a < b else 1
    if pre1 is None and pre2 is None:
        return 0
    if pre1 is None and pre2 is not None:
        return 1
    if pre1 is not None and pre2 is None:
        return -1
    ids1 = pre1.split('.')
    ids2 = pre2.split('.')
    for i1, i2 in zip(ids1, ids2):
        c = _cmp_ident(i1, i2)
        if c != 0:
            return c
    if len(ids1) != len(ids2):
        return -1 if len(ids1) < len(ids2) else 1
    return 0

def semver_sort(versions):
    indexed = list(enumerate(versions))
    def cmp(a, b):
        c = _compare(a[1], b[1])
        if c != 0:
            return c
        return a[0] - b[0]
    indexed.sort(key=functools.cmp_to_key(cmp))
    return [v for _, v in indexed]

